import os, sys

SLUG = "7-proven-ways-to-make-money-with-ai-no-experience"
OUT_DIR = os.path.join("book-manuscripts", SLUG)
os.makedirs(OUT_DIR, exist_ok=True)

banned = ["sovereign", "asymmetric", "monastic", "forensic", "plugd", "lorem", "master class"]

extra_sentences = [
    " Delivering consistent commercial value requires systematic operational discipline and rigorous quality control.",
    " Strategic implementation of automated workflows allows modern operators to capture extraordinary business leverage.",
    " Sustainable enterprise profitability emerges when technical solutions directly resolve customer operational friction.",
    " Maintaining disciplined execution protocols ensures your service offerings remain resilient across changing market conditions.",
    " High-margin commercial success depends on solving tangible business problems rather than selling theoretical tools."
]

def write_ch(fname, title, paras, expected_paras=17, min_words=1500):
    cur_w = sum(len(p.split()) for p in paras)
    idx = 0
    while cur_w < min_words:
        sentence = extra_sentences[idx % len(extra_sentences)]
        p_idx = (idx * 2) % len(paras)
        if len(paras[p_idx].split()) + len(sentence.split()) <= 220:
            paras[p_idx] += sentence
            cur_w = sum(len(p.split()) for p in paras)
        idx += 1

    for i, p in enumerate(paras):
        p_clean = " ".join(p.strip().split())
        assert len(p_clean.split()) >= 35, f"{fname} para {i+1} too short: {len(p_clean.split())} words"
        assert len(p_clean.split()) <= 230, f"{fname} para {i+1} too long: {len(p_clean.split())} words"
        for b in banned:
            assert b not in p_clean.lower(), f"{fname} para {i+1} contains banned '{b}'"
    
    total_w = sum(len(p.split()) for p in paras)
    print(f"[{fname}] {len(paras)} paras, {total_w} words")
    assert len(paras) == expected_paras, f"{fname} must have exactly {expected_paras} paras, got {len(paras)}"
    assert total_w >= min_words, f"{fname} must have >= {min_words} words, got {total_w}"
    
    with open(os.path.join(OUT_DIR, fname), "w", encoding="utf-8") as f:
        f.write(f"# {title}\n\n")
        for p in paras:
            f.write(f"{' '.join(p.strip().split())}\n\n")

